import{_ as t,o as a,c as i,a0 as o}from"./chunks/framework.CShDTZbC.js";const u=JSON.parse('{"title":"Authentication","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/authentication.md","filePath":"getting-started/authentication.md"}'),s={name:"getting-started/authentication.md"};function r(n,e,d,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><p>Cognimemo supports three authentication methods:</p><h2 id="google-sso" tabindex="-1">Google SSO <a class="header-anchor" href="#google-sso" aria-label="Permalink to &quot;Google SSO&quot;">​</a></h2><p>Sign in with your Google account via WorkOS. No configuration needed — just click &quot;Sign in with Google&quot; on the login page.</p><h2 id="email-password" tabindex="-1">Email + Password <a class="header-anchor" href="#email-password" aria-label="Permalink to &quot;Email + Password&quot;">​</a></h2><p>Create an account with email and password. Passwords are managed by WorkOS User Management.</p><h2 id="api-keys" tabindex="-1">API Keys <a class="header-anchor" href="#api-keys" aria-label="Permalink to &quot;API Keys&quot;">​</a></h2><p>API keys are used for programmatic access (SDK, MCP, CLI). Keys are:</p><ul><li>Prefixed with <code>cmk_live_</code></li><li>SHA-256 hashed at rest</li><li>Scoped to specific operations</li><li>Revocable at any time</li></ul><h3 id="scopes" tabindex="-1">Scopes <a class="header-anchor" href="#scopes" aria-label="Permalink to &quot;Scopes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><code>retain</code></td><td>Store memories</td></tr><tr><td><code>recall</code></td><td>Retrieve memories</td></tr><tr><td><code>reflect</code></td><td>Generate reflections</td></tr><tr><td><code>files.retain</code></td><td>Store file memories</td></tr><tr><td><code>graph:read</code></td><td>Read entity graph</td></tr><tr><td><code>mcp</code></td><td>Use with MCP server</td></tr></tbody></table><h3 id="creating-keys" tabindex="-1">Creating Keys <a class="header-anchor" href="#creating-keys" aria-label="Permalink to &quot;Creating Keys&quot;">​</a></h3><ol><li>Go to <strong>Settings → API Keys</strong></li><li>Click &quot;Create key&quot;</li><li>Select scopes</li><li>Copy the key — it&#39;s shown only once</li></ol><h3 id="using-keys" tabindex="-1">Using Keys <a class="header-anchor" href="#using-keys" aria-label="Permalink to &quot;Using Keys&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer cmk_live_...&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://dev-api.cognimemo.com/v1/...</span></span></code></pre></div>',15)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
